#!/usr/bin/env python3
from pathlib import Path
import json,re
R=Path(__file__).resolve().parents[1];DATE='2026-09-22';V='1.0.0-design'
def read(p):return json.loads((R/p).read_text())
def out(name,rows,base='data/v1'):(R/base/(name+'.json')).write_text(json.dumps({'version':V,'as_of':DATE,'records':rows},ensure_ascii=False,indent=2)+'\n')
ps=[]
for l in (R/'research/design/projects.psv').read_text().splitlines():
 if not l or l.startswith('#'):continue
 a=l.split('|');assert len(a)==10,a[0]
 id,title,req,obj,steps,deliver,reference,fail,limit,hours=a
 ps.append({'id':id,'title':title,'prerequisites':req.split(),'learning_objective':obj,'data_plan':'Default: generated hypothetical/synthetic data with seed, parameter manifest and no third-party market observations. Optional real data requires written entitlement, retention/export terms and timestamped lineage.','steps':steps.split(';'),'deliverables':deliver,'reference_behavior':reference,'rubric':{'cash_and_numerical_correctness':30,'assumptions_and_data_lineage':20,'validation_and_failure_cases':25,'decision_and_limitations':15,'reproducibility_accessibility':10},'pass_score':85,'critical_failure':'Units, cash, assignment, leaked evaluation or false entitlement claim blocks mastery regardless of score.','failure_cases':fail.split(';'),'limitations':limit,'study_hours':[int(x) for x in hours.split(',')],'estimate_basis':'Design estimate for implementation, audit and one revision; prior competencies assumed.','status':'project_specification','real_money_required':False,'noncoding_route':'PR01 foundational cash tables available without code; audit supplied ledgers for other projects, but this does not award executable-code competency.'})
out('projects',ps)
su=read('research/inventory/supplemental.json');caps=[];cards=[];branches=[]
links=[['PR01'],['PR02','PR03','PR05','PR07'],['PR04','PR06','PR09','PR10'],['PR01','PR08'],['PR07','PR11'],['PR08','PR09','PR10','PR11','PR12'],['PR08','PR12']]
for i,l in enumerate(su['capstones']['markdown'].splitlines()):
 m=re.match(r'(\d+)\. \*\*(.*?):\*\* (.*)',l)
 if m:
  n=int(m[1]);caps.append({'id':f'C{n:02d}','title':m[2],'original_brief':m[3],'project_ids':links[n-1],'assessment_policy':'POL-01','source':su['capstones']['source'],'line':su['capstones']['line']+i,'status':'preserved_and_integrated'})
for i,l in enumerate(su['decision_card']['markdown'].splitlines()):
 m=re.match(r'(\d+)\. (.*)',l)
 if m:cards.append({'id':'DC'+m[1].zfill(2),'question':m[2],'source':su['decision_card']['source'],'line':su['decision_card']['line']+i,'required_in_capstones':['C04','C06','C07']})
for i,l in enumerate(su['specialization_branches']['markdown'].splitlines()):
 if l.startswith('|') and not l.startswith('| Track') and not l.startswith('|---'):
  cells=[x.strip() for x in l.strip('|').split('|')]
  if len(cells)==3:branches.append({'id':f'BR{len(branches)+1:02d}','title':cells[0],'original_module_scope':cells[1],'depth':cells[2],'source':su['specialization_branches']['source'],'line':su['specialization_branches']['line']+i,'status':'preserved_specialization; resolve prerequisites through competency graph'})
assert len(caps)==7 and len(cards)==23 and len(branches)==7,(len(caps),len(cards),len(branches))
out('capstones',caps);out('decision_cards',cards);out('specializations',branches)
out('assessment_policies',[{'id':'POL-01','version':1,'threshold':85,'critical_errors':['contract_units','cash_obligation','assignment','leverage','loss_bound','data_leakage','unlawful_data_use'],'states':['viewed','self_completed','attempted','demonstrated_mastery'],'evidence':'Versioned response, rubric, assessor identity/role, source snapshot, score, critical errors and fresh transfer task. P01 defines fields, not an application learner model.','retry':'Preserve earlier attempt; targeted remediation; unseen variant. No completion by attendance or investment returns.','calibration':'85% is an inherited pedagogical default, not psychometrically validated certification. P17 pilots must evaluate item reliability and accessibility.'}])
# Dated rules: verified historical provisions are distinct from a certified current contract master.
rules=[]
def rule(id,instrument,juris,typ,value,unit,url,circ,pub,eff,status,scope,unc,prior=None,to=None):
 rules.append({'id':id,'instrument':instrument,'jurisdiction':juris,'rule_type':typ,'value':value,'unit':unit,'source_url':url,'circular_identifier':circ,'publication_date':pub,'effective_from':eff,'effective_to':to,'verification_date':DATE,'supersedes':prior or [],'superseded_by':[],'review_status':status,'scope':scope,'uncertainty':unc,'review_owner':'curriculum rules editor','review_interval_days':7 if juris=='India' else 30,'publication_eligible':status=='historical_verified','unknown_date_reason':'Null end date means not established, not proof of perpetual validity.'})
rule('RULE-IN-01','NSE individual-stock derivatives','India','settlement','physical','delivery','https://www.sebi.gov.in/sebi_data/attachdocs/dec-2018/1546255335099.pdf','SEBI/HO/MRD/DOPI/CIR/P/2018/161','2018-12-31','2019-04-01','historical_verified','Staged mandate: bottom50 April2019,next50 July2019,remaining October2019; newstock entrants physical.','Historical mandate verified; exact present delivery deadlines require current NCL/broker chain.',['SEBI/HO/MRD/DOPI/CIR/P/2018/67'])
