rule('RULE-IN-03','NSE indices and stock derivatives covered in notice','India','expiry transition','Tuesday','weekday','https://nsearchives.nseindia.com/web/sites/default/files/inline-files/FAOP68747.pdf','NSE/FAOP/68747','2025-06-25','2025-06-26','historical_verified','Existing <=Aug31 unchanged except longdatedadjustment; newly generated >=Sep1expiry Tuesday; longdatedrealign July31EOD.','Need contractmaster, holidayadjustment andlatercircular search for specific currentseries.',['NSE/FAOP/68685'])
for id,sym,old,new in [('04','NIFTY',75,65),('05','BANKNIFTY',35,30),('06','FINNIFTY',65,60),('07','MIDCPNIFTY',140,120),('08','NIFTYNXT50',25,25)]:
 rule('RULE-IN-'+id,sym,'India','market lot transition',new,'index units/contract','https://nsearchives.nseindia.com/content/circulars/FAOP70616.pdf','NSE/FAOP/70616','2025-10-03','2025-10-28','historical_verified',f'Old lot{old}; new generation after Oct28EOD; old weekly/monthly through Dec30; longdatedconversion Dec30EOD.','This notice establishes transition, not a September2026 master-file certificate.',['SEBI/HO/MRD/TPD-1/P/CIR/2024/00181'])
rule('RULE-IN-09','BSE SENSEX weekly; SENSEX/BANKEX/SENSEX50 monthly; stock monthly','India','expiry transition','Thursday / last Thursday as product-specific','weekday','https://www.bseindia.com/markets/MarketInfo/DispNewNoticesCirculars.aspx?page=20250623-59','BSE20250623-59','2025-06-23','2025-09-01','historical_verified','SENSEX weekly Thursday; listedindexmonthly andstockmonthly lastThursday. Existing<=Aug31 unchanged; masters updated on stated differing dates.','Lateramendments/currentlots not certified. SENSEXweeklyfutures cease afterAug12; optionscontinue.',['BSE20250617-11','BSE20241128-70','BSE20240430-50'])
