rule('RULE-IN-11','NSE F&O and CAS eligible cash securities','India','closing-auction transition',None,'time','https://www.nseindia.com/static/products-services/closing-auction-session','NSE/CMTR/74466; NSE/FAOP/74467','2026-05-29',None,'quarantined_current_rule','Officialpage identifies CAS timings and F&O close15:40; cashCASphase1 only F&O stocks.','Operativenotice retrieval404; commencement/amendmentchain notverified. No fixedtime adopted.')
rule('RULE-IN-12','NIFTY India FPI150 and all current listings','India','contract availability',None,'contract list','https://www.nseindia.com/static/products-services/equity-derivatives-contract-specifications','NSE specifications page','2026-08-11',None,'quarantined_current_rule','New FPI150 name appears beyond original fiveindexscope; verify introduction/masterbeforeassigning currentavailability.','Currentmaster, weekly/monthlychain, restrictions,positionlimits,marginoffsets andfreezequantities stillrequire series-specific check.')
rule('RULE-IN-13','NSE clearing overview all equity derivatives','India','settlement conflict','blanket cash wording rejected','text','https://www.nseclearing.in/clearing-settlement/equity-derivatives/settlement-mechanism','overview updated2023-09-27','2023-09-27',None,'rejected_conflicting_summary','Retain as conflict evidence; do not use its broad cash exercise sentence for individualstocks.','Specific SEBIphysical mandate and NCL2026deliverynotice outrank genericoverview.')
rule('RULE-US-01','OCC-issued standardized options','US','exercise and assignment','style/product/broker specific','procedure','https://www.theocc.com/getmedia/a151a9ae-d784-4a15-bdeb-23a029f50b70/riskstoc.pdf','ODD June2024','2024-06',None,'reviewed_principle','ChII/VIII/X differentiateexercise, settlement andbrokerinstructions; no one universalmultiplier orcutoff.','Checkcurrentsupplements andexactproduct/brokerdeadline before operationaluse.')
rule('RULE-US-02','US portfolio-margin accounts','US','margin eligibility',None,'account-specific','https://www.finra.org/rules-guidance/rulebooks/finra-rules/4210','FINRA4210(g)',None,None,'quarantined_current_rule','Teach strategybased versusportfoliomargin andbrokeroverlays.','Fullamendment/effectivedatechain notread; no accountthresholdcertified.')
