rule('RULE-GLOBAL-01','EU/UK OTC and Eurex products','EU/UK','collateral/reporting comparison',None,'product/legal entity','https://www.esma.europa.eu/publications-and-data/interactive-single-rulebook/emir/article-41-margin-requirements-0','EMIRArt41; UKEMIR; EurexPrisma',None,None,'quarantined_current_rule','Scope comparison only; R43/R46/R69 retained.','Exactclearingthresholds, eligibility andeffectiveamendments outsidepublication.')
initial=read('research/evidence/source-checks-2026-09-21.json')['records']
algo=next(x for x in initial if x['id']=='Q025')
rule('RULE-IN-14','Retail broker/exchange algorithmic API access','India','access and restrictions',None,'account and strategy specific',algo['url'],'SEBI retail-algorithmic framework and extension chain; Q025/Q026',None,None,'quarantined_current_rule','Educational API topics do not authorize trading, deployment or redistribution.','Original framework/extension observations preserved; subsequent implementation circulars and broker permissions not certified.')
rule('RULE-IN-15','NIFTY/BANKNIFTY/FINNIFTY/MIDCPNIFTY/NIFTYNXT50/FPI150','India','weekly/monthly availability',None,'listed series','https://www.nseindia.com/static/products-services/equity-derivatives-contract-specifications','NSE specification directory; current master required',None,None,'quarantined_current_rule','Observed page separates NIFTY weekly from other monthly listings; quarterly/longdated details are product specific.','Current daily master and introduction/discontinuation chain not reconciled; no universal weekly availability adopted.')
rule('RULE-IN-16','NSE index and stock F&O accounts','India','SPAN, delivery margin and offsets',None,'currency and percent','https://www.nseindia.com/static/products-services/equity-derivatives-contract-information','Product/capital/expiry-specific clearing circular chain not certified',None,None,'quarantined_current_rule','Teach scenario margin versus loss, collateral haircuts, expiry/delivery margin and broker add-ons.','Current risk parameter files, offset rules and implementation dates must be obtained for the exercise date.')
rule('RULE-IN-17','BSE SENSEX/BANKEX/SENSEX50 and stock derivatives','India','current lot, availability and settlement procedures',None,'contract units and dates','https://www.bseindia.com/markets/MarketInfo/DispNewNoticesCirculars.aspx?page=20250623-59','BSE current master/amendments pending;20250623-59 only proves historical transition',None,None,'quarantined_current_rule','Record index/stock and product-specific fields separately.','No current BSE lot or exact clearing deadline certified; original R60 file format is insufficient.')
for n,charge in enumerate(['brokerage','exchange and clearing fees','GST on applicable services','stamp duty','other applicable regulatory levies'],1):
 rule('RULE-IN-FEE-'+str(n),'India exchange-traded derivatives','India',charge,None,'applicable charge basis','https://www.nseindia.com/static/products-services/equity-derivatives-contract-information','Current primary schedule/statute and broker tariff required',None,None,'quarantined_current_rule','Separate this charge from STT; identify payer, calculation base, rounding and effective dates.','No rate or universal taxable base adopted; publication blocked until primary schedule and applicable account/product verified.')
rule('RULE-IN-18','India exchange-traded index/stock derivatives','India','position limits, quantity freezes and restrictions',None,'contracts, notional or percent as applicable','https://www.nseindia.com/static/products-services/equity-derivatives-contract-information','Current exchange/SEBI limit and restriction notices required',None,None,'quarantined_current_rule','Limits, surveillance restrictions and eligibility need product/account-specific worksheets.','No current threshold adopted; contract directory is a discovery source, not completed notice-chain review.')
out('market_rules',rules)
# Exact topic assignments for bounded reviewed claims supplement module reading candidates.
a=read('data/v1/associations.json')['records']
for n,rid,tids,scope,claim in [('01','RX01',['M22.01'],'Full exercising article; holder/member/broker layers','CL01'),('02','RX02',['M28.01'],'Parity assumptions and synthetic replication','CL02'),('03','R35',['M37.P01'],'Sections2–3: European totalvariance anddensity conditions, not Americanquoteprocessing','CL05'),('04','RX04',['M37.P01'],'Benchmarkscope andconclusion; dividendsnotstudied','CL06'),('05','R56',['M66.P01'],'Table5 pp17–19 versus prose; quarantine numericalheadlines','CL10'),('06','RX15',['M57.01'],'Commonpitfalls12.2 leakage','CL12')]:
 a.append({'id':'A-EXACT-'+n,'resource_id':rid,'competency_id':'C-'+tids[0].split('.')[0],'topic_ids':tids,'reading_scope':scope,'purpose':'Bounded evidence/teaching assignment; not inheritance.','status':'selected_reading','evidence_claim_ids':[claim]})
out('associations',a)
# Item-level supplemental mappings, beyond preserved complete prose blocks.
m=read('data/v1/source_mappings.json')['records']
for kind,rows in [('capstone',caps),('decision_card',cards),('specialization',branches)]:
 for x in rows:m.append({'id':'MAP-'+x['id'],'original_id':x['id'],'kind':kind,'provenance':{'source':x['source'],'line':x['line']},'canonical_ids':[x['id']],'disposition':'retained','note':'Original item individually addressable; complete surrounding policy also archived.'})
out('source_mappings',m)
print('Supplement:',len(ps),'projects',len(caps),'capstones',len(cards),'cards',len(rules),'rules')
